TLM.f("Sancti/05-31",{"officium":"Beatæ Mariæ Virginis Reginæ","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=festivitate"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","sections":{"Introitus":[{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Maríæ Vírginis Regínæ: de cuius solemnitáte gaudent Angeli, et colláudant Fílium Dei. (Alleluia, alleluia.)"},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Effúndit cor meum verbum bonum: dico ego carmen meum Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Maríæ Vírginis Regínæ: de cuius solemnitáte gaudent Angeli, et colláudant Fílium Dei. (Alleluia, alleluia.)"}],"Oratio":[{"k":"text","la":"Concéde nobis, quǽsumus, Dómine: ut, qui solemnitátem beátæ Maríæ Vírginis Regínæ nostræ celebrámus; eius muníti præsídio, pacem in præsénti et glóriam in futúro cónsequi mereámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio libri Sapientiæ"},{"k":"ref","la":"Eccli 24:5, 7, 9-11, 30-31"},{"k":"text","la":"Ego ex ore Altíssimi prodívi, primogénita ante omnem creatúram; ego in altíssimis habitávi, et thronus meus in colúmna nubis. In omni terra steti; et in omni pópulo, et in omni gente primátum hábui, et ómnium excelléntium et humílium corda virtúte calcávi. Qui audit me, non confundétur, et qui operántur in me, non peccábunt; qui elúcidant me, vitam ætérnam habébunt."}],"Graduale":[{"k":"ref","la":"Apo 19:16"},{"k":"text","la":"Ipse habet in vestiménto et in fémore suo scriptum: Rex regum et Dóminus dominántium."},{"k":"ref","la":"Ps 44:10"},{"k":"text","la":"Regína adstat ad déxteram eius, ornáta auro ex Ophir. Allelúia, allelúia."},{"k":"text","la":"Salve, Regína misericórdiæ, tu nos ab hoste prótege, et mortis hora súscipe. Allelúia.","mark":"V"}],"GradualeP":[{"k":"text","la":"Alleluia, alleluia."},{"k":"text","la":"Beáta es, Virgo María, quæ sub Cruce Dómini sustinuísti. Allelúia.","mark":"V"},{"k":"text","la":"Nunc cum eo regnas in ætérnum. Allelúia.","mark":"V"}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequentia sancti Evangelii secundum Lucam."},{"k":"ref","la":"Luc 1:26-33"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriel a Deo in civitátem Galilǽæ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Ioseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena: Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne eius: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce concípies in útero, et páries fílium, et vocábis nomen eius Iesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David patris eius: et regnábit in domo Iacob in ætérnum, et regni eius non erit finis."}],"Offertorium":[{"k":"text","la":"Regáli ex progénie María exórta refúlget; cuius précibus nos adiuvári, mente et spíritu devotíssime póscimus. (Allelúia.)"}],"Secreta":[{"k":"text","la":"Accipe, quǽsumus, Dómine, múnera lætántis Ecclésiæ, et, beátæ Vírginis Maríæ Regínæ suffragántibus méritis, ad nostræ salútis auxílium proveníre concéde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Regína mundi digníssima, María Virgo perpétua, intercéde pro nostra pace et salúte, quæ genuísti Christum Dóminum, Salvatórem ómnium."}],"Postcommunio":[{"k":"text","la":"Celebrátis solémniis, Dómine, quæ pro sanctæ Maríæ Regínæ nostræ festivitáte (memória) perégimus: eius, quǽsumus, nobis intercessióne fiant salutária; in cuius honóre sunt exsultánter impléta."},{"k":"macro","name":"Per Dominum"}],"Introitus1":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}]},"hr":{"3210b5c3d2e0301e":{"t":"Ps 44, 2\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Djevice Marije Kraljice, čijoj se svetkovini raduju anđeli i hvale Sina Božjega.\n(Ps 44, 2) Iz srca mi navire radosna riječ, pripovjedam pjesmu svoju Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Djevice Marije Kraljice, čijoj se svetkovini raduju anđeli i hvale Sina Božjega.\n[Napomena M.B. ovdje je, za razliku npr. od Bezgrešnog Srca Marijinog na 22. dan kolovoza, za Ps 44,2 korišten tzv. Pijev psaltir, izdan u vrijeme Pija XII., a ne Jeronimov \"galikanski\" iz Vulgate. Razlika je u riječima \"eructavit(Vg)-effundit(P) te opera(Vg)-carmen(P), pri čemu se eructavit-effundit u oba slučaja hrvatski može prevesti kao \"navrijeti\".]","v":"aleluia aleluia → ∅; aleluia aleluia → ∅","kn":"Radujmo se svi u Gospodinu svetkujuči blagdan na Čast Djevice Marije, na koje svetkovinu vesele.se anđeli i hvale Sina Božjega. (Ps. 44, 2) Iz mog srca izvire divna pjesma: djela su moja namijenjena kralju. Slava Ocu . . . Radujmo se . . .","knRef":"Kniewald 1942, str. 638–639 (snimka 320) (OCR)"},"5105198242008651":{"t":"<i>Pomolimo se</i>.\nPodaj nam, molimo, Gospodine, da mi koji slavimo svetkovinu [spomen] blažene Marije Djevice naše kraljice, osigurani njezinom zaštitom zavrijedimo postići mir u sadašnjosti i slavu u budućnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0ff90d67e7d72288":{"t":"Sir 24, 5 i 7, 9-11, 30-31\nČitanje knjige Mudrosti. Izašla sam iz usta Svevišnjega prije svakoga stvora, postavila sam stan u visinama, a prijestolje u stupu oblaka. Zaustavila sam se u svakom kraju i kod svakoga plemena, preuzela sam vodstvo svakog naroda i dobrotom sam osvojila srca sviju, velikih i malenih. Koji mene sluša, neće se postidjeti, koji mene nasljeduje neće griješiti, a koji me slave, postići će vječni život."},"a875e80d71b3f7f1":null,"0d2deefaf1d705d0":{"t":"Lk 1, 26-33\nSlijedi sveto Evanđelje po Luki. U ono vrijeme posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se, i razmišljala je što taj pozdrav znači. Anđeo joj reče: Nemoj se bojati, Marijo, jer si našla milost u Boga: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. Gospodin će mu dati prijestolje njegova oca Davida, i vladat će Jakovljevom kućom dovijeka, i njegovu kraljevstvu neće biti svršetka."},"6b871a8d71576161":{"t":"Rođena od kraljevske loze blista Marija, Srcem i umom pobožno molimo da nas pomogne njezin zagovor.","v":"aleluia → ∅"},"8649dacfaa34bd5d":{"t":"Primi, molimo, Gospodine, darove radosne Crkve, i daj da posredovanjem zasluga blažene Djevice Marije Kraljice budu na pomoć našeg spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo, Gospodine, naše darove, dostojno prikazane, i dopusti zagovorom zasluga \\ Sv. Matija 24. II. blaženoga Valentina, mučenika Tvoga, da nam budu u pomoći za vječno spasenje, po G. n.","knRef":"Kniewald 1942, str. 510–511 (snimka 256) (OCR)"},"006ab57f0d571d6b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o svetkovini</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"94e6cd036a358145":{"t":"Predostojna Kraljice svijeta, Marijo, vazda Djevice, koja si porodila Krista Gospodina, Spasitelja cijelog svijeta, zauzmi se za nas da postignemo mir i spasenje.","v":"aleluia → ∅","kn":"Najdostojnija kraljice svijeta, Marijo, vazda Djevice, koja si rodila Krista Gospodina, Spasitelja svima, moli za naš mir i spasenje.","knRef":"Kniewald 1942, str. 640–641 (snimka 321) (OCR)"},"129ecd22094b2de2":{"t":"<i>Pomolimo se</i>.\nPošto smo. Gospodine, izvršili svečanosti, koje smo obavili radi svetkovine svete Marije, naše Kraljice, molimo, da nam budu spasonosne po zagovoru one, kojoj su u čast radosno obavljene.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8be085f30fcf08ed":{"t":"Ps 44, 2\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Djevice Marije Kraljice, čijoj se svetkovini raduju anđeli i hvale Sina Božjega, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 44, 2) Iz srca mi navire radosna riječ, pripovjedam pjesmu svoju Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Djevice Marije Kraljice, čijoj se svetkovini raduju anđeli i hvale Sina Božjega, <i>aleluja</i>, <i>aleluja</i>.\n[Napomena M.B. ovdje je, za razliku npr. od Bezgrešnog Srca Marijinog na 22. dan kolovoza, za Ps 44,2 korišten tzv. Pijev psaltir, izdan u vrijeme Pija XII., a ne Jeronimov \"galikanski\" iz Vulgate. Razlika je u riječima \"eructavit(Vg)-effundit(P) te opera(Vg)-carmen(P), pri čemu se eructavit-effundit u oba slučaja hrvatski može prevesti kao \"navrijeti\".]","kn":"Radujmo se svi u Gospodinu svetkujuči blagdan na Čast Djevice Marije, na koje svetkovinu vesele.se anđeli i hvale Sina Božjega. (Ps. 44, 2) Iz mog srca izvire divna pjesma: djela su moja namijenjena kralju. Slava Ocu . . . Radujmo se . . , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 638–639 (snimka 320) (OCR)"},"5cdb5fca3d82f272":{"t":"<i>Aleluja</i>, <i>aleluja</i>.\nBlažena si, Djevo Marijo, koja si trpjela pod križem Gospodnjim, <i>aleluja</i>.\nSada s njim zajedno kraljuješ zauvijek, <i>aleluja</i>."},"93d1b6905e64d06a":{"t":"Rođena od kraljevske loze blista Marija, Srcem i umom pobožno molimo da nas pomogne njezin zagovor, <i>aleluja</i>."},"cf2c3cce970f5a68":{"t":"Predostojna Kraljice svijeta, Marijo, vazda Djevice, koja si porodila Krista Gospodina, Spasitelja cijelog svijeta, zauzmi se za nas da postignemo mir i spasenje, <i>aleluja</i>.","kn":"Najdostojnija kraljice svijeta, Marijo, vazda Djevice, koja si rodila Krista Gospodina, Spasitelja svima, moli za naš mir i spasenje, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 640–641 (snimka 321) (OCR)"}}});
